package com.brandempiricism.etocrm.capabilities.catalog;
import com.brandempiricism.etocrm.capabilities.CapabilityApplicationApi;import java.util.*;import org.springframework.stereotype.Service;
@Service class CapabilityService implements CapabilityApplicationApi{private final CapabilityRepository capabilities;CapabilityService(CapabilityRepository capabilities){this.capabilities=capabilities;}public Capability get(UUID id){return capabilities.findById(id).map(CapabilityService::view).orElseThrow(()->new IllegalArgumentException("Capability does not exist."));}public List<Capability> list(){return capabilities.findAll().stream().map(CapabilityService::view).toList();}private static Capability view(CapabilityEntity c){return new Capability(c.id,c.name,c.description,c.active);}}
